// plank-join checker - part of Shipshape fitting out
// Reads all production JS files for @planks and @planks-provisional annotations,
// reads all feature files for step definitions (Given/When/Then),
// and reports mismatches. Exits non-zero on any mismatch.

import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, extname } from 'node:path';
import { glob } from 'node:fs';

const ROOT = new URL('..', import.meta.url).pathname;
let exitCode = 0;

// --- 1. Collect all step definition patterns from features/support ---
const supportDir = join(ROOT, 'features', 'support');
const stepPatterns = new Set();
const stepDefFiles = readdirSync(supportDir).filter(f => f.endsWith('.js'));
for (const f of stepDefFiles) {
  const src = readFileSync(join(supportDir, f), 'utf8');
  // Match Given(/pattern/ or 'pattern' or "pattern") or similar
  const matches = src.matchAll(/(?:Given|When|Then)\(\s*(?:\/([^/]*)\/|'([^']*)'|"([^"]*)")\s*,/g);
  for (const m of matches) {
    stepPatterns.add(m[1] || m[2] || m[3]);
  }
}

// --- 2. Collect all @planks and @planks-provisional from production JS files ---
const jsDir = join(ROOT, 'js');
const planks = {}; // pattern -> array of { file, line }
const provisionalPlanks = {}; // scenarioRef -> array of { file, line }
const allTokens = [];

function scanDir(dir) {
  if (!statSync(dir, { throwIfNoEntry: false })) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      scanDir(full);
    } else if (entry.name.endsWith('.js')) {
      const src = readFileSync(full, 'utf8');
      const lines = src.split('\n');
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        // @planks("pattern")
        const pMatch = line.match(/@planks\(\s*"([^"]+)"\s*\)/);
        if (pMatch) {
          const pattern = pMatch[1];
          if (!planks[pattern]) planks[pattern] = [];
          planks[pattern].push({ file: full, line: i + 1 });
          allTokens.push({ type: 'planks', value: pattern, file: full, line: i + 1 });
        }
        // @planks-provisional("ref")
        const ppMatch = line.match(/@planks-provisional\(\s*"([^"]+)"\s*\)/);
        if (ppMatch) {
          const ref = ppMatch[1];
          if (!provisionalPlanks[ref]) provisionalPlanks[ref] = [];
          provisionalPlanks[ref].push({ file: full, line: i + 1 });
          allTokens.push({ type: 'planks-provisional', value: ref, file: full, line: i + 1 });
        }
      }
    }
  }
}
scanDir(jsDir);

// --- 3. Check @planks against step patterns ---
for (const [pattern, locations] of Object.entries(planks)) {
  if (!stepPatterns.has(pattern)) {
    console.error(`MISMATCH: @planks("${pattern}") matches no step definition`);
    for (const loc of locations) {
      console.error(`  at ${loc.file}:${loc.line}`);
    }
    exitCode = 1;
  }
}

// --- 4. Check @planks-provisional against @captain scenarios in features ---
// Read all feature files for @captain scenarios
const featuresDir = join(ROOT, 'features');
const captainScenarios = new Set();

function scanFeatures(dir) {
  if (!statSync(dir, { throwIfNoEntry: false })) return;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = join(dir, entry.name);
    if (entry.isDirectory()) {
      scanFeatures(full);
    } else if (entry.name.endsWith('.feature')) {
      const relativePath = entry.name; // features/name.feature
      const src = readFileSync(full, 'utf8');
      const lines = src.split('\n');
      let currentScenario = null;
      let hasCaptainTag = false;
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i].trim();
        if (line.startsWith('@captain')) {
          hasCaptainTag = true;
        }
        const sMatch = line.match(/^(?:Scenario|Scenario Outline):\s*(.+)$/);
        if (sMatch) {
          if (currentScenario && hasCaptainTag) {
            const ref = `features/${entry.name}:${currentScenario}`;
            captainScenarios.add(ref);
          }
          currentScenario = sMatch[1].trim();
          hasCaptainTag = false;
        }
      }
      // Last scenario
      if (currentScenario && hasCaptainTag) {
        const ref = `features/${entry.name}:${currentScenario}`;
        captainScenarios.add(ref);
      }
    }
  }
}
scanFeatures(featuresDir);

for (const [ref, locations] of Object.entries(provisionalPlanks)) {
  if (!captainScenarios.has(ref)) {
    console.error(`MISMATCH: @planks-provisional("${ref}") names a scenario without @captain tag`);
    for (const loc of locations) {
      console.error(`  at ${loc.file}:${loc.line}`);
    }
    exitCode = 1;
  }
}

// --- 5. Report summary ---
console.log(`plank-join: ${allTokens.length} tokens, ${stepPatterns.size} step patterns, ${captainScenarios.size} @captain scenarios`);
for (const p of stepPatterns) {
  console.log(`  step: "${p}"`);
}
for (const t of allTokens) {
  console.log(`  ${t.type}: "${t.value}" at ${t.file}:${t.line}`);
}

process.exit(exitCode);

